<?php $page_title='Deliveries'; require 'layout.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->prepare('UPDATE deliveries SET status=?, delivered_at=IF(?="delivered",NOW(),delivered_at) WHERE id=?')->execute([$_POST['status'],$_POST['status'],(int)$_POST['id']]);flash('success','Delivery status updated.');redirect('deliveries.php');}
$rows=$pdo->query("SELECT d.*,f.title, n.name ngo, u.name volunteer FROM deliveries d JOIN food_donations f ON f.id=d.food_id LEFT JOIN ngos n ON n.id=d.ngo_id LEFT JOIN volunteers v ON v.id=d.volunteer_id LEFT JOIN users u ON u.id=v.user_id ORDER BY d.created_at DESC")->fetchAll();
?><section class="admin-page-head"><div><span class="kicker">ADMIN / LOGISTICS</span><h1>Deliveries</h1><p>Monitor pickup, transit and delivery completion.</p></div></section><div class="admin-table-card"><div class="table-wrap"><table><thead><tr><th>Food</th><th>Volunteer</th><th>NGO</th><th>Route</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['title'])?></b><small>#<?=intval($r['id'])?></small></td><td><?=e($r['volunteer']?:'Unassigned')?></td><td><?=e($r['ngo']?:'Unassigned')?></td><td><?=e($r['pickup_address']?:'—')?> → <?=e($r['delivery_address']?:'—')?></td><td><span class="badge <?=badge_class($r['status'])?>"><?=e($r['status'])?></span></td><td><form class="inline-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option>assigned</option><option>pickup</option><option>picked_up</option><option>on_the_way</option><option>delivered</option><option>cancelled</option></select><button class="mini-btn">Update</button></form></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6">No delivery records yet. Deliveries will appear here when logistics records are created.</td></tr><?php endif;?></tbody></table></div></div><?php require 'footer.php'; ?>
